// Each example exposes its own data and a concrete artifact, not a generic work checklist.
const m=(input,columns,rows,why)=>({input,visual:{type:'matrix',columns,rows,caption:why},why});
const d=(input,start,question,yes,no,why)=>({input,visual:{type:'decision',start,question,yes,no,caption:why},why});
const n=(input,nodes,edges,why)=>({input,visual:{type:'network',nodes:nodes.map(([title,text],i)=>({id:String(i),title,text})),edges:edges.map(([from,to,label])=>({from:String(from),to:String(to),label})),caption:why},why});
const p=(input,items,why)=>({input,visual:{type:'process',items:items.map(([title,text])=>({title,text})),caption:why},why});
const b=(input,unit,items,max,why,threshold)=>({input,visual:{type:'bars',items:items.map(([label,value])=>({label,value})),max,unit,...(threshold===undefined?{}:{threshold}),caption:why},why});
const h=(input,root,branches,why)=>({input,visual:{type:'tree',root,branches:branches.map(([title,...items])=>({title,items})),caption:why},why});
export {m,d,n,p,b,h};

